// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/agents/TaskModesShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Task modes: the Tasks dropdown on its New task form, ported from the app's
 * TaskComposer (src/tasks/TaskForm.tsx) inside TasksPanel's shell
 * (src/tasks/TasksPanel.tsx, TasksButton.tsx) and styled by the app's own
 * stylesheet. The mode switch works like the app's: One, Parallel, Chain and
 * Race each show their own agents, steps or lines, and Start says what it
 * would start (it starts nothing). While the scene is on screen it walks the
 * four modes; any click or keystroke in it hands the form over.
 */
import { useRef, useState, type ReactNode, type RefObject } from "react";
import { ArrowDown, ArrowLeft, ArrowUp, CornerDownLeft, Eye, FolderOpen, GitBranch, Link2, ListTodo, Plus, ShieldCheck, X, type LucideIcon } from "lucide-react";
import { AgentMark, Brand, TopBar, Window } from "../../home/AppUI";
import { PANEL, Shot } from "../../home/Chrome";
import { windowPanels } from "../../home/Dropdowns";
import { ActiveCanvas, ToolsBar, WorkspaceTabs } from "../../home/Interactive";
import { usePanelLoop } from "../../home/panel-loops";
import { CORNER, SessionTile, topRight } from "../../home/Scenes";
import { MacIcon, SelectButton, useAutoGrow } from "./parts";

type TaskMode = "one" | "parallel" | "chain" | "race";
type Role = "write" | "review" | "fix" | "plan" | "build" | "custom";

// The app's MODES (src/tasks/TaskForm.tsx).
const MODES: readonly { id: TaskMode; label: string; hint: string }[] = [
  { id: "one", label: "One", hint: "One agent on one task" },
  { id: "parallel", label: "Parallel", hint: "One task per line, each with its own agent, worktree and branch, all at once" },
  { id: "chain", label: "Chain", hint: "Steps one after another in one worktree, in any order: write, review, fix, plan, build or your own" },
  { id: "race", label: "Race", hint: "The same prompt to several agents; keep the best, discard the rest" },
];

// ROLE_LABEL and ROLE_HINT (src/tasks/taskChain.ts).
const ROLE_LABEL: Record<Role, string> = { write: "Write", review: "Review", fix: "Fix", plan: "Plan", build: "Build", custom: "Custom" };
const ROLE_HINT: Record<Role, string> = {
  write: "Does the task as written",
  review: "Reviews the branch so far without changing code",
  fix: "Fixes what the last review found, or problems in the changes so far",
  plan: "Writes a plan without changing code",
  build: "Implements the last plan, or the task when there is none",
  custom: "Your own instruction for this step",
};

type FormAgent = "claude" | "codex" | "gemini";

/** Each agent's default mode as the form shows it (server/lib/session-agents.js), with the app's modeIcon. */
const AGENT: Record<FormAgent, { label: string; mode: string; description: string; icon: LucideIcon }> = {
  claude: { label: "Claude Code", mode: "Ask", description: "Asks before edits and commands", icon: ShieldCheck },
  codex: { label: "Codex", mode: "Ask", description: "Read-only sandbox; asks before edits and other commands", icon: Eye },
  gemini: { label: "Gemini CLI", mode: "Ask", description: "Asks before edits and commands", icon: ShieldCheck },
};

/* The demo task: the race the homepage's Tasks card shows, written here for
   each mode. Parallel takes one task per line. */
const PROMPT = "Add search to the notes page";
const LINES = [PROMPT, "Show a word count under each note", "Let notes be sorted by title"];
const RACE: FormAgent[] = ["claude", "codex", "gemini"];
// The Write, then review, then fix preset: the first agent writes and fixes, a second one reviews.
const CHAIN: { role: Role; agent: FormAgent }[] = [
  { role: "write", agent: "claude" },
  { role: "review", agent: "codex" },
  { role: "fix", agent: "claude" },
];

/* The loop: the race at rest (the page's frame), then One, Parallel with its
   lines typed in, Chain, and back. */
const ROUND: { mode: TaskMode; hold: number }[] = [
  { mode: "race", hold: 3600 },
  { mode: "one", hold: 2400 },
  { mode: "parallel", hold: 3400 },
  { mode: "chain", hold: 3600 },
];
const LINE_KEY_MS = 28;

/** One agent row (the app's agentRow): extras around the agent and its mode. */
function AgentRow({
  agent,
  label,
  lead,
  before,
  after,
  remove,
  withMode = true,
}: {
  agent: FormAgent;
  label: string;
  lead?: ReactNode;
  before?: ReactNode;
  after?: ReactNode;
  remove?: string;
  withMode?: boolean;
}) {
  const info = AGENT[agent];
  const ModeIcon = info.icon;
  return (
    <div className="ns-seg ns-seg-extra task-agent-seg" role="group" aria-label={label}>
      {lead}
      {before}
      <SelectButton ariaLabel={label} className="ns-pill task-agent-pick" icon={<AgentMark agent={agent} size={13} />} label={info.label} />
      {withMode ? (
        <SelectButton
          ariaLabel={`${label} mode`}
          className="ns-pill ns-mode"
          title={`${info.label} mode: ${info.description}`}
          icon={<ModeIcon size={13} />}
          label={info.mode}
        />
      ) : null}
      {after}
      {remove ? (
        <button type="button" className="ns-clear task-agent-remove" aria-label={remove} title="Remove">
          <X size={11} aria-hidden="true" />
        </button>
      ) : null}
    </div>
  );
}

function TaskComposer({ panelRef }: { panelRef: RefObject<HTMLDivElement> }) {
  const [mode, setMode] = useState<TaskMode>("race");
  const [prompt, setPrompt] = useState(PROMPT);
  const promptRef = useRef<HTMLTextAreaElement>(null);
  // The lines the loop is typing, finished at once if it stops halfway.
  const typing = useRef<string | null>(null);
  useAutoGrow(promptRef, prompt, { minLines: mode === "parallel" ? 3 : 1, maxLines: mode === "parallel" ? 8 : 6 });

  usePanelLoop(
    panelRef,
    async (wait) => {
      for (const step of ROUND) {
        setMode(step.mode);
        if (step.mode === "parallel") {
          // One task per line: the next two are typed under the first.
          const full = LINES.join("\n");
          typing.current = full;
          for (let at = PROMPT.length + 1; at <= full.length; at += 1) {
            setPrompt(full.slice(0, at));
            await wait(LINE_KEY_MS);
          }
          typing.current = null;
        } else setPrompt(PROMPT);
        await wait(step.hold);
      }
    },
    () => {
      if (typing.current) setPrompt(typing.current);
      typing.current = null;
    },
  );

  // What Start would launch, as the app counts it.
  const lines = mode === "parallel" ? prompt.split(/\r?\n/).map((line) => line.trim()).filter(Boolean) : [];
  const problem = !prompt.trim() ? "Describe the task for the agents." : mode === "parallel" && lines.length < 2 ? "Write one task per line, at least two." : null;
  const startLabel =
    mode === "parallel" ? `Start ${Math.max(lines.length, 2)} tasks` : mode === "chain" ? "Start chain" : mode === "race" ? `Start ${RACE.length} agents` : "Start task";

  return (
    <form className="new-session-form task-form" aria-label="New task" onSubmit={(event) => event.preventDefault()}>
      <div className="notification-actions menu-head tasks-head">
        <span className="menu-head-title tasks-title">New task</span>
        <div className="tasks-head-tools">
          <button type="button" className="icon-btn tasks-back" aria-label="Back" title="Back (Esc)">
            <ArrowLeft size={15} aria-hidden="true" />
          </button>
        </div>
      </div>
      <div className="ns-composer">
        <div className="ns-composer-line task-composer-line">
          <ListTodo size={16} className="muted-icon" aria-hidden="true" />
          <textarea
            ref={promptRef}
            className="ns-input task-prompt-input"
            rows={1}
            value={prompt}
            aria-label="What should the agents do?"
            placeholder={mode === "parallel" ? "One task per line…" : "Describe the task…"}
            onChange={(event) => setPrompt(mode === "parallel" ? event.target.value : event.target.value.replace(/[\r\n]+/g, " "))}
          />
          <button
            type="submit"
            className="btn btn-accent ns-create"
            disabled={!!problem}
            title={problem ?? `${startLabel} (⌘ Enter). Each agent works in its own worktree on a new pzza/ branch.`}
          >
            {startLabel}
            <CornerDownLeft size={12} strokeWidth={2.2} aria-hidden="true" />
          </button>
        </div>
      </div>

      <div className="ns-seg" role="group" aria-label="Where to work">
        <SelectButton ariaLabel="Device" className="ns-pill" icon={<MacIcon />} label="This Device" />
        <span className="ns-pill-path has-value">
          <button type="button" className="path-field ns-pill" title="~/fieldnotes/web">
            <FolderOpen size={13} className="path-field-icon" />
            <span className="path-field-value">~/fieldnotes/web</span>
          </button>
        </span>
        <SelectButton ariaLabel="Base branch" className="ns-pill" icon={<GitBranch size={13} />} label="main" />
      </div>

      <div className="usage-seg task-mode-seg" role="radiogroup" aria-label="Task mode">
        {MODES.map((item) => (
          <button
            key={item.id}
            type="button"
            role="radio"
            aria-checked={mode === item.id}
            className={mode === item.id ? "on" : ""}
            title={item.hint}
            onClick={() => setMode(item.id)}
          >
            {item.label}
          </button>
        ))}
      </div>

      {mode === "chain" ? (
        <>
          <div className="ns-seg ns-seg-extra task-agent-seg" role="group" aria-label="Chain">
            <SelectButton ariaLabel="Chain preset" className="ns-pill task-agent-pick" icon={<Link2 size={13} />} label="Write, then review, then fix" />
          </div>
          <div className="task-steps" role="group" aria-label="Steps">
            {CHAIN.map((step, index) => {
              const name = `Step ${index + 1}`;
              return (
                <div key={name} className="task-step-edit">
                  <AgentRow
                    agent={step.agent}
                    label={`${name}: ${ROLE_LABEL[step.role]}`}
                    before={
                      <SelectButton ariaLabel={`${name} role`} className="ns-pill task-step-role" title={ROLE_HINT[step.role]} label={ROLE_LABEL[step.role]} />
                    }
                    after={
                      <>
                        <button
                          type="button"
                          className="ns-clear task-agent-remove"
                          aria-label={`Move ${name.toLowerCase()} up`}
                          title="Move up"
                          disabled={index === 0}
                        >
                          <ArrowUp size={11} aria-hidden="true" />
                        </button>
                        <button
                          type="button"
                          className="ns-clear task-agent-remove"
                          aria-label={`Move ${name.toLowerCase()} down`}
                          title="Move down"
                          disabled={index === CHAIN.length - 1}
                        >
                          <ArrowDown size={11} aria-hidden="true" />
                        </button>
                      </>
                    }
                    remove={`Remove ${name.toLowerCase()}`}
                  />
                </div>
              );
            })}
          </div>
          <button type="button" className="ns-toggle task-add-agent" title="Add a step after the last one; pick its role, agent and mode">
            <Plus size={12} aria-hidden="true" />
            Add a step
          </button>
        </>
      ) : mode === "parallel" ? (
        <>
          <AgentRow
            agent="claude"
            label="Agent"
            lead={
              <span className="task-step-label" aria-hidden="true">
                Every task
              </span>
            }
          />
          {lines.map((line, index) => (
            <AgentRow
              key={index}
              agent="claude"
              label={`Agent for line ${index + 1}`}
              withMode={false}
              lead={
                <span className="task-step-label task-line-label" title={line}>
                  {index + 1}. {line}
                </span>
              }
            />
          ))}
        </>
      ) : (
        <>
          {(mode === "one" ? RACE.slice(0, 1) : RACE).map((agent, index) => (
            <AgentRow
              key={agent}
              agent={agent}
              label={`Agent ${index + 1}`}
              remove={mode === "race" ? `Remove ${AGENT[agent].label}` : undefined}
            />
          ))}
          {mode === "race" ? (
            <button type="button" className="ns-toggle task-add-agent" title="Race another agent on the same prompt; keep the best">
              <Plus size={12} aria-hidden="true" />
              Add an agent
            </button>
          ) : null}
        </>
      )}
    </form>
  );
}

/** The Tasks dropdown (TasksButton: Dropdown width 380) on its New task view. */
function TaskModesPanel() {
  const panel = useRef<HTMLDivElement>(null);
  return (
    <div
      ref={panel}
      className="menu menu-panel notifications-panel tasks-menu-panel"
      style={{ right: PANEL.edge, top: PANEL.top, left: "auto", width: 380 }}
    >
      <div className="menu-body latest-notifications tasks-panel">
        <TaskComposer panelRef={panel} />
      </div>
    </div>
  );
}

export function TaskModesShot() {
  const box = topRight(CORNER.width);
  return (
    <Shot id="tasks" width={CORNER.width} height={CORNER.height}>
      <Window style={box}>
        <TopBar>
          <Brand />
          <WorkspaceTabs />
          <ToolsBar initial="tasks" panels={{ ...windowPanels({ height: box.height }), tasks: <TaskModesPanel /> }} />
        </TopBar>
        <ActiveCanvas
          initial={1}
          style={{ gridTemplateColumns: "1fr 1fr", gridTemplateRows: "1fr 1fr" }}
          tiles={[
            <SessionTile key="api" id="api" capture="api-86" kbd="⌘1" />,
            <SessionTile key="web" id="web" capture="web-86" kbd="⌘2" />,
            <SessionTile key="release" id="release" capture="release-86" kbd="⌘3" />,
            <SessionTile key="docs" id="docs" capture="docs-86" kbd="⌘4" />,
          ]}
        />
      </Window>
    </Shot>
  );
}
